extends "res://htd/htd_test.gd"

func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale main.tscn deve caricarsi senza errori"):
		return
	var east := main.get_node_or_null("BlockEast") as Node3D
	if not check("east", east != null, "Nella scena serve un Node3D chiamato BlockEast figlio di Island"):
		return
	var east_top := main.get_node_or_null("BlockEast/BlockEastTop") as Node3D
	if not check("east_top", east_top != null, "BlockEast deve avere un figlio Node3D chiamato BlockEastTop"):
		return
	check("east_pos", east.position.is_equal_approx(Vector3(6.0, 0.0, 1.0)), "BlockEast deve avere posizione (6, 0, 1) (trovata: %s)" % str(east.position))
	check("east_rot", absf(east.rotation_degrees.y - (-30.0)) < 0.1, "BlockEast deve avere rotazione Y di -30 gradi (trovata: %.1f)" % east.rotation_degrees.y)
	check("east_scale", east.scale.is_equal_approx(Vector3(1.0, 2.0, 1.0)), "BlockEast deve avere scala (1, 2, 1) (trovata: %s)" % str(east.scale))
	check("east_top_pos", east_top.position.is_equal_approx(Vector3(0.0, 2.5, 0.0)), "BlockEastTop deve avere posizione locale (0, 2.5, 0) (trovata: %s)" % str(east_top.position))
	if check("has_fn", has_function(main, "get_top_block_positions"), "main.gd deve contenere la funzione get_top_block_positions"):
		var res = main.call("get_top_block_positions")
		if check("res_array", res is Array and res.size() == 3, "get_top_block_positions deve restituire un Array con 3 elementi"):
			var expected_top: Vector3 = (main.get_node("BlockBase/BlockTop") as Node3D).global_position
			var expected_bridge: Vector3 = (main.get_node("BlockWest/BlockWestBridge") as Node3D).global_position
			var expected_east_top: Vector3 = east_top.global_position
			check("pos_0", (res[0] as Vector3).is_equal_approx(expected_top), "Il primo elemento deve essere la posizione globale di BlockTop")
			check("pos_1", (res[1] as Vector3).is_equal_approx(expected_bridge), "Il secondo elemento deve essere la posizione globale di BlockWestBridge")
			check("pos_2", (res[2] as Vector3).is_equal_approx(expected_east_top), "Il terzo elemento deve essere la posizione globale di BlockEastTop")
